function hash(seed,a,b=0){let n=Math.imul((seed^Math.imul(a+7,2654435761)^Math.imul(b+11,1597334677))>>>0,2246822507);return (n^(n>>>13))>>>0}
function pick(seed,a,list,b=0){return list[hash(seed,a,b)%list.length]}
function context(s,n=s.turn){FamilyWorld.ensure(s);const k=s.kingdom,r=s.race,rank=s.rank,rel=FamilyWorld.chooseRelative(s,n);return {place:pick(s.seed,n,places[k],k),npc:FantasyNames.npc(s,n+40),relative:rel.alive?rel.name:'คนรู้จักในย่าน',relativeId:rel.alive?rel.id:'',household:s.household.title,rank:typeof HumanOrigins==='undefined'?HumanOrigins.classLabel(s):HumanOrigins.classLabel(s),job:s.job===null?'ผู้แสวงหาเส้นทาง':JOBS[s.job][0],landmark:landmarks[k],tradition:raceWays[r][0],issue:regionalTroubles[k][0],custom:raceWays[r][1],kingdomPressure:regionalTroubles[k][1],origin:s.race!==0&&typeof SpeciesSociety!=='undefined'?SpeciesSociety.label(s):FAMILIES[s.household.typeIndex]}}
function fill(s,text,c=context(s)){const values={kingdom:KINGDOMS[s.kingdom][0],race:RACES[s.race][0],family:s.family,place:c.place,npc:c.npc,pet:s.pet?.name||'สหายตัวน้อย',petline:s.pet?s.pet.name+'นอนข้างเก้าอี้ของคุณ':'สายลมพัดชายเสื้ออย่างแผ่วเบา',relative:c.relative,household:c.household,rank:c.rank,job:c.job,landmark:c.landmark,tradition:c.tradition,issue:c.issue,custom:c.custom,kingdomPressure:c.kingdomPressure,origin:c.origin,home:LifeContent.homes[s.rank]};return String(text??'').replace(/\{(kingdom|race|family|place|npc|pet|petline|relative|household|rank|job|landmark|tradition|issue|custom|kingdomPressure|origin|home)\}/g,(_,k)=>values[k]??'')}
function description(s,n=s.turn){const k=s.kingdom,r=s.race,rank=s.rank;const v=pick(s.seed,n,[`ใน${KINGDOMS[k][0]} ผู้คนจำกันจากทางเดินที่กลับบ้าน ไม่ใช่ตราประจำตัว`, `เสียงรอบตัวของ${RACES[r][0]}ทำให้วันธรรมดามีจังหวะเฉพาะที่คนต่างถิ่นต้องใช้เวลาจึงจะเข้าใจ`, `บ้านของ${s.family}มีขนบเล็ก ๆ ที่สมาชิกทุกคนช่วยกันรักษา`, `ฐานะ${HumanOrigins.classLabel(s)}ทำให้คุณเห็นด้านของเมืองที่คนในหอคอยมักไม่เคยพบ`],k+r+rank);return v}
